import ChatBot from "./chat-bot"

export default function Page() {
  return (
    <div className="mx-auto w-full max-w-3xl px-4 py-10 md:px-6 md:py-14">
      <ChatBot />
    </div>
  )
}

"use client"

import { cn } from "@/lib/utils"
import { RotateCcw, Copy, Share2, ThumbsUp, ThumbsDown, CornerDownRight } from "lucide-react"
import { useChatAnimation } from "./hooks/use-chat-animation"
import MessageBubble from "./components/message-bubble"
import ThinkLabel from "./components/typing-indicator"
import ChatInput from "./components/chat-input"
import { SUGGESTIONS } from "./lib/config"
import "./styles/chat-bot.css"

export default function ChatBot() {
  const { phase, inputText, userMessage, botText, thinkSeconds, settled } = useChatAnimation()
  const showMessages = userMessage !== null
  const isPaused = phase === "paused"

  return (
    <div className="cb-root">
      <div className="cb-layout">

        {/* Messages panel */}
        <div className={cn("cb-messages-panel", showMessages && "cb-messages-panel--visible")}>

          {userMessage && (
            <MessageBubble role="user" text={userMessage} />
          )}

          <div className="cb-bot-area">
            <ThinkLabel phase={phase} thinkSeconds={thinkSeconds} />

            {botText !== null && (
              <MessageBubble
                role="bot"
                text={botText}
                isTyping={phase === "botTyping"}
              />
            )}

            {/* Reveal container — always in DOM so height animates, children mount at paused so animations retrigger */}
            <div className={cn("cb-reveal", isPaused && "cb-reveal--open")}>
              <div className="cb-reveal-inner">
                {isPaused && (
                  <>
                    <div className="cb-actions">
                      <button className="cb-action-btn" aria-label="Retry"><RotateCcw size={14} /></button>
                      <button className="cb-action-btn" aria-label="Copy"><Copy size={14} /></button>
                      <button className="cb-action-btn" aria-label="Share"><Share2 size={14} /></button>
                      <button className="cb-action-btn" aria-label="Thumbs up"><ThumbsUp size={14} /></button>
                      <button className="cb-action-btn" aria-label="Thumbs down"><ThumbsDown size={14} /></button>
                    </div>
                    <div className="cb-suggestions">
                      {SUGGESTIONS.map((s) => (
                        <button key={s} className="cb-chip">
                          <CornerDownRight size={12} className="cb-chip-icon" aria-hidden />
                          {s}
                        </button>
                      ))}
                    </div>
                  </>
                )}
              </div>
            </div>

          </div>

        </div>

        {/* Input bar */}
        <ChatInput value={inputText} phase={phase} settled={settled} />

      </div>
    </div>
  )
}

interface MessageBubbleProps {
  role: "user" | "bot"
  text: string
  isTyping?: boolean
}

export default function MessageBubble({ role, text, isTyping }: MessageBubbleProps) {
  if (role === "user") {
    return (
      <div className="cb-user-row">
        <div className="cb-user-bubble">{text}</div>
      </div>
    )
  }

  return (
    <p className="cb-bot-text">
      {text}
      {isTyping && <span className="cb-bot-cursor" aria-hidden />}
    </p>
  )
}

import { Lightbulb } from "lucide-react"
import type { Phase } from "../hooks/use-chat-animation"

interface ThinkLabelProps {
  phase: Phase
  thinkSeconds: number
}

export default function ThinkLabel({ phase, thinkSeconds }: ThinkLabelProps) {
  if (phase === "botThinking") {
    return (
      <div className="cb-think-row">
        <Lightbulb size={13} className="cb-think-icon cb-think-pulse" aria-hidden />
        <span className="cb-think-text">Thinking…</span>
      </div>
    )
  }

  if (phase === "botTyping" || phase === "paused") {
    return (
      <div className="cb-think-row">
        <Lightbulb size={13} className="cb-think-icon" aria-hidden />
        <span className="cb-think-text">Thought for {thinkSeconds}s</span>
      </div>
    )
  }

  return null
}

import { cn } from "@/lib/utils"
import { Paperclip, ArrowUp } from "lucide-react"
import type { Phase } from "../hooks/use-chat-animation"

interface ChatInputProps {
  value: string
  phase: Phase
  settled: boolean
}

export default function ChatInput({ value, phase, settled }: ChatInputProps) {
  const isSending = phase === "userSending"
  const isLoading = isSending || phase === "botThinking" || phase === "botTyping" || (phase === "paused" && !settled)
  const showCursor = phase === "userTyping"

  return (
    <div className={cn("cb-input-pill", isSending && "cb-input-sending")}>
      <Paperclip size={16} className="cb-input-icon" aria-hidden />
      <div className="cb-input-field">
        {value ? (
          <span className="cb-input-text">{value}</span>
        ) : (
          <span className="cb-input-placeholder">Message…</span>
        )}
        {showCursor && <span className="cb-input-cursor" aria-hidden />}
      </div>
      <div className="cb-input-right">
        <button
          className={cn("cb-send-btn", isSending && "cb-send-btn-active")}
          aria-label="Send message"
          tabIndex={-1}
        >
          {isLoading ? <span className="cb-spinner" aria-hidden /> : <ArrowUp size={15} strokeWidth={2.5} />}
        </button>
      </div>
    </div>
  )
}

import { useReducer, useLayoutEffect, useMemo, useRef } from "react"

import {
  EXCHANGE,
  TYPE_CHAR_MS,
  PRE_SEND_DELAY_MS,
  SEND_FLASH_MS,
  BOT_THINK_MS,
  BOT_TYPE_CHAR_MS,
  LOOP_PAUSE_MS,
} from "../lib/config"

export type Phase =
  | "userTyping"
  | "userSending"
  | "botThinking"
  | "botTyping"
  | "paused"

type State = {
  phase: Phase
  charIdx: number
  userSent: boolean
  thinkSeconds: number
  settled: boolean
}

type Action =
  | { type: "ADVANCE_CHAR" }
  | { type: "SET_PHASE"; phase: Phase; charIdx?: number; userSent?: boolean }
  | { type: "TICK_THINK" }
  | { type: "SET_SETTLED" }
  | { type: "RESET" }

const INITIAL: State = { phase: "userTyping", charIdx: 0, userSent: false, thinkSeconds: 0, settled: false }

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "ADVANCE_CHAR":
      return { ...state, charIdx: state.charIdx + 1 }
    case "SET_PHASE":
      return {
        phase: action.phase,
        charIdx: action.charIdx ?? state.charIdx,
        userSent: action.userSent ?? state.userSent,
        thinkSeconds: action.phase === "botThinking" ? 0 : state.thinkSeconds,
        settled: false,
      }
    case "TICK_THINK":
      return { ...state, thinkSeconds: state.thinkSeconds + 1 }
    case "SET_SETTLED":
      return { ...state, settled: true }
    case "RESET":
      return INITIAL
    default:
      return state
  }
}

export function useChatAnimation() {
  const [state, dispatch] = useReducer(reducer, INITIAL)
  const { phase, charIdx, userSent, thinkSeconds, settled } = state
  const scrollRef = useRef<HTMLDivElement>(null)

  const { question, answer } = EXCHANGE

  // ── Derived display values ─────────────────────────────────────────────────

  const inputText = useMemo(() => {
    if (phase === "userTyping") return question.slice(0, charIdx)
    if (phase === "userSending") return question
    return ""
  }, [phase, charIdx, question])

  const userMessage: string | null = userSent ? question : null

  const botText = useMemo((): string | null => {
    if (phase === "botTyping") return answer.slice(0, charIdx)
    if (phase === "paused") return answer
    return null
  }, [phase, charIdx, answer])

  // ── Animation driver ───────────────────────────────────────────────────────

  useLayoutEffect(() => {
    let t: ReturnType<typeof setTimeout>

    switch (phase) {
      case "userTyping":
        if (charIdx < question.length) {
          t = setTimeout(() => dispatch({ type: "ADVANCE_CHAR" }), TYPE_CHAR_MS)
        } else {
          t = setTimeout(
            () => dispatch({ type: "SET_PHASE", phase: "userSending" }),
            PRE_SEND_DELAY_MS,
          )
        }
        break

      case "userSending":
        t = setTimeout(
          () =>
            dispatch({
              type: "SET_PHASE",
              phase: "botThinking",
              charIdx: 0,
              userSent: true,
            }),
          SEND_FLASH_MS,
        )
        break

      case "botThinking":
        t = setTimeout(
          () => dispatch({ type: "SET_PHASE", phase: "botTyping", charIdx: 0 }),
          BOT_THINK_MS,
        )
        break

      case "botTyping":
        if (charIdx < answer.length) {
          t = setTimeout(() => dispatch({ type: "ADVANCE_CHAR" }), BOT_TYPE_CHAR_MS)
        } else {
          t = setTimeout(
            () => dispatch({ type: "SET_PHASE", phase: "paused" }),
            400,
          )
        }
        break

      case "paused":
        t = setTimeout(() => dispatch({ type: "RESET" }), LOOP_PAUSE_MS)
        break
    }

    return () => clearTimeout(t)
  }, [phase, charIdx, question, answer])

  // ── Think-seconds ticker ───────────────────────────────────────────────────

  useLayoutEffect(() => {
    if (phase !== "botThinking") return
    const id = setInterval(() => dispatch({ type: "TICK_THINK" }), 1000)
    return () => clearInterval(id)
  }, [phase])

  // ── Settle after chips animate in (~500ms into paused) ─────────────────────

  useLayoutEffect(() => {
    if (phase !== "paused") return
    const t = setTimeout(() => dispatch({ type: "SET_SETTLED" }), 1150)
    return () => clearTimeout(t)
  }, [phase])

  // ── Auto-scroll ────────────────────────────────────────────────────────────

  useLayoutEffect(() => {
    const el = scrollRef.current
    if (!el) return
    el.scrollTop = el.scrollHeight - el.clientHeight
  }, [userMessage, botText, phase])

  return { phase, inputText, userMessage, botText, scrollRef, thinkSeconds, settled }
}

/** Typing speed for the simulated user input */
export const TYPE_CHAR_MS = 55

/** Pause after the user finishes typing before "sending" */
export const PRE_SEND_DELAY_MS = 420

/** How long the "sending" flash lasts */
export const SEND_FLASH_MS = 280

/** How long the bot "thinks" before responding */
export const BOT_THINK_MS = 2200

/** Typing speed for the bot response */
export const BOT_TYPE_CHAR_MS = 30

/** How long the completed conversation sits before looping */
export const LOOP_PAUSE_MS = 3600

export const EXCHANGE = {
  question: "Why was my transfer flagged?",
  answer: "Your $4,200 transfer to a new payee triggered a routine compliance check. It's been reviewed and cleared — funds will arrive by end of day. No action needed on your end.",
}

export const SUGGESTIONS = [
  "Set this payee as trusted",
  "View my transfer history",
] as const

/* chat-bot — Claude.ai-inspired animated chat */

/* ── Tokens — light ───────────────────────────────────────────────────────── */

.cb-root {
  --cb-bg: #ffffff;

  --cb-user-bubble-bg: #18181b;
  --cb-user-bubble-text: #fafafa;

  --cb-bot-text: #18181b;
  --cb-think-color: #71717a;

  --cb-input-bg: #f4f4f5;
  --cb-input-border: #e4e4e7;
  --cb-input-text: #18181b;
  --cb-input-placeholder: #a1a1aa;
  --cb-input-cursor: #71717a;
  --cb-input-icon: #a1a1aa;

  --cb-model-color: #71717a;
  --cb-model-chevron: #a1a1aa;

  --cb-send-bg: #18181b;
  --cb-send-text: #ffffff;

  --cb-action-color: #a1a1aa;
  --cb-action-hover-bg: #f4f4f5;
  --cb-action-hover-color: #71717a;

  --cb-chip-border: #e4e4e7;
  --cb-chip-text: #71717a;
  --cb-chip-icon: #a1a1aa;
}

/* ── Tokens — dark ────────────────────────────────────────────────────────── */

.dark .cb-root {
  --cb-bg: #000000;

  --cb-user-bubble-bg: #1c1c1f;
  --cb-user-bubble-text: #f4f4f5;

  --cb-bot-text: #e4e4e7;
  --cb-think-color: #71717a;

  --cb-input-bg: #0d0d0d;
  --cb-input-border: #2a2a2a;
  --cb-input-text: #e4e4e7;
  --cb-input-placeholder: #52525b;
  --cb-input-cursor: #71717a;
  --cb-input-icon: #52525b;

  --cb-model-color: #71717a;
  --cb-model-chevron: #52525b;

  --cb-send-bg: #ffffff;
  --cb-send-text: #000000;

  --cb-action-color: #52525b;
  --cb-action-hover-bg: #1c1c1f;
  --cb-action-hover-color: #a1a1aa;

  --cb-chip-border: #27272a;
  --cb-chip-text: #a1a1aa;
  --cb-chip-icon: #52525b;
}

/* ── Root ─────────────────────────────────────────────────────────────────── */

.cb-root {
  padding: 48px 24px;
  display: flex;
  justify-content: center;
}

/* ── Layout ───────────────────────────────────────────────────────────────── */

.cb-layout {
  width: 100%;
  max-width: 600px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* ── Messages panel ───────────────────────────────────────────────────────── */

.cb-messages-panel {
  display: flex;
  flex-direction: column;
  gap: 24px;
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}

.cb-messages-panel--visible {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

/* ── User message ─────────────────────────────────────────────────────────── */

.cb-user-row {
  display: flex;
  justify-content: flex-end;
}

.cb-user-bubble {
  background: var(--cb-user-bubble-bg);
  color: var(--cb-user-bubble-text);
  padding: 10px 18px;
  border-radius: 9999px;
  font-size: 14px;
  line-height: 1.5;
  max-width: 80%;
  animation: cb-bubble-in 0.45s cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* ── Bot area ─────────────────────────────────────────────────────────────── */

.cb-bot-area {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ── Reveal container — animates height without layout shifts ─────────────── */

.cb-reveal {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.cb-reveal--open {
  grid-template-rows: 1fr;
}

.cb-reveal-inner {
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-top: 0;
  transition: padding-top 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

.cb-reveal--open .cb-reveal-inner {
  padding-top: 14px;
}

/* ── Think label ──────────────────────────────────────────────────────────── */

.cb-think-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 14px;
}

.cb-think-icon {
  color: var(--cb-think-color);
  flex-shrink: 0;
}

.cb-think-text {
  font-size: 13px;
  color: var(--cb-think-color);
}

.cb-think-pulse {
  animation: cb-think-pulse 2.2s ease-in-out infinite;
}

/* ── Bot text ─────────────────────────────────────────────────────────────── */

.cb-bot-text {
  font-size: 15px;
  line-height: 1.7;
  color: var(--cb-bot-text);
  margin: 0;
  white-space: pre-line;
}

.cb-bot-cursor {
  display: inline-block;
  width: 2px;
  height: 0.9em;
  margin-left: 2px;
  vertical-align: text-bottom;
  background: var(--cb-bot-text);
  opacity: 0.5;
  border-radius: 1px;
  animation: cb-blink 0.9s step-start infinite;
}

/* ── Action buttons ───────────────────────────────────────────────────────── */

.cb-actions {
  display: flex;
  align-items: center;
  gap: 2px;
}

.cb-action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border: none;
  background: transparent;
  color: var(--cb-action-color);
  cursor: default;
  border-radius: 7px;
  transition: color 0.15s ease, background 0.15s ease;
  animation: cb-fade-up 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.cb-action-btn:nth-child(1) { animation-delay: 40ms; }
.cb-action-btn:nth-child(2) { animation-delay: 110ms; }
.cb-action-btn:nth-child(3) { animation-delay: 180ms; }
.cb-action-btn:nth-child(4) { animation-delay: 250ms; }
.cb-action-btn:nth-child(5) { animation-delay: 320ms; }

.cb-action-btn:hover {
  color: var(--cb-action-hover-color);
  background: var(--cb-action-hover-bg);
}

/* ── Suggestion chips ─────────────────────────────────────────────────────── */

.cb-suggestions {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.cb-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px 8px 10px;
  background: transparent;
  border: 1px solid var(--cb-chip-border);
  border-radius: 10px;
  color: var(--cb-chip-text);
  font-size: 13px;
  cursor: default;
  text-align: left;
  width: fit-content;
  transition: border-color 0.15s ease;
  animation: cb-chip-in 0.45s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.cb-chip:nth-child(1) { animation-delay: 500ms; }
.cb-chip:nth-child(2) { animation-delay: 640ms; }

.cb-chip-icon {
  color: var(--cb-chip-icon);
  flex-shrink: 0;
}

/* ── Input pill ───────────────────────────────────────────────────────────── */

.cb-input-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--cb-input-bg);
  border: 1px solid var(--cb-input-border);
  border-radius: 9999px;
  padding: 11px 10px 11px 16px;
  transition: border-color 0.15s ease;
}

.cb-input-sending {
  opacity: 0.5;
  transition: opacity 0.15s ease;
}

.cb-input-icon {
  color: var(--cb-input-icon);
  flex-shrink: 0;
}

.cb-input-field {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
}

.cb-input-text {
  font-size: 14px;
  color: var(--cb-input-text);
  line-height: 1.5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cb-input-placeholder {
  font-size: 14px;
  color: var(--cb-input-placeholder);
  line-height: 1.5;
  user-select: none;
}

.cb-input-cursor {
  display: inline-block;
  width: 2px;
  height: 14px;
  margin-left: 1px;
  vertical-align: text-bottom;
  background: var(--cb-input-cursor);
  border-radius: 1px;
  animation: cb-blink 0.9s step-start infinite;
}

/* ── Right side of input ──────────────────────────────────────────────────── */

.cb-input-right {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

/* ── Loading spinner ──────────────────────────────────────────────────────── */

.cb-spinner {
  display: block;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, currentColor 25%, transparent);
  border-top-color: currentColor;
  animation: cb-spin 0.65s linear infinite;
}

/* ── Send button ──────────────────────────────────────────────────────────── */

.cb-send-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--cb-send-bg);
  color: var(--cb-send-text);
  border: none;
  cursor: default;
  flex-shrink: 0;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.cb-send-btn-dim {
  opacity: 0.28;
}

.cb-send-btn-active {
  opacity: 1;
  animation: cb-send-pulse 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

/* ── Keyframes ────────────────────────────────────────────────────────────── */

@keyframes cb-bubble-in {
  from {
    opacity: 0;
    transform: scale(0.91) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes cb-chip-in {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes cb-fade-up {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes cb-blink {
  0%, 45% { opacity: 1; }
  55%, 100% { opacity: 0; }
}

@keyframes cb-think-pulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}

@keyframes cb-send-pulse {
  0% { transform: scale(1); }
  40% { transform: scale(0.76); }
  100% { transform: scale(1); }
}

@keyframes cb-input-send {
  0% { opacity: 1; }
  30% { opacity: 0.38; }
  100% { opacity: 1; }
}

@keyframes cb-spin {
  to { transform: rotate(360deg); }
}
